/**
 * `buildPostCompactMessages` devuelve `CompactableMessage[]`, cuyo campo
 * `content` es `unknown` -- más amplio que el `string | readonly unknown[]`
 * que declara `AgentMessageBody`. El contenido real que produce la
 * compactación siempre es texto o un array de bloques (misma guarda que ya
 * usa `messageAdapters.ts` para el mismo campo); esta función la aplica sin
 * cambiar el valor cuando la guarda se cumple.
 */
function toAgentMessages(messages: CompactableMessage[]): Message[] {
  return messages.map((message): Message => {
    const body = message.message
    if (body === undefined) return { ...message, message: undefined }
    const content = body.content
    const narrowedContent =
      typeof content === 'string' || Array.isArray(content) ? content : undefined
    return { ...message, message: { ...body, content: narrowedContent } }
  })
}

